            # print(f"Skipping malformed row in PDF: {row} - Error: {e}")
            continue

        employees[record['ID']] = record
    return employees

def parse_excel():
    df = pd.read_excel("/root/employees_current.xlsx")
    employees = {}

    records = df.to_dict(orient='records')
    for record in records:
        # Type enforcement
        try:
            record['Salary'] = int(record['Salary'])
            record['Years'] = int(record['Years'])
            record['Score'] = float(record['Score'])
        except (ValueError, TypeError) as e:
            print(f"Skipping malformed row in Excel: {record} - Error: {e}")
            continue

        employees[record['ID']] = record
    return employees

def compare_data(pdf_data, excel_data):
    deleted_employees = []
    modified_employees = []

    # Check for deleted
    for emp_id in pdf_data:
        if emp_id not in excel_data:
            deleted_employees.append(emp_id)

    # Check for modified
    for emp_id in excel_data:
        if emp_id in pdf_data:
            pdf_emp = pdf_data[emp_id]
            excel_emp = excel_data[emp_id]

            # Fields to check
            fields = ['First', 'Last', 'Dept', 'Position', 'Salary', 'Years', 'Location', 'Score']

            for field in fields:
                old_val = pdf_emp.get(field)
                new_val = excel_emp.get(field)

                if old_val != new_val:
                    modified_employees.append({
                        "id": emp_id,
                        "field": field,
                        "old_value": old_val,
                        "new_value": new_val
                    })

    # Sort results
    deleted_employees.sort()
    modified_employees.sort(key=lambda x: x['id'])

    return {
        "deleted_employees": deleted_employees,
        "modified_employees": modified_employees
    }

def main():
    try:
        print("Reading PDF...")
        pdf_data = parse_pdf()
        print(f"Found {len(pdf_data)} records in PDF.")

        print("Reading Excel...")
        excel_data = parse_excel()
        print(f"Found {len(excel_data)} records in Excel.")

        print("Comparing...")
        result = compare_data(pdf_data, excel_data)

        output_path = "/root/diff_report.json"
        with open(output_path, "w") as f:
            json.dump(result, f, indent=2)

        print(f"Report written to {output_path}")
        # Print preview
        print(json.dumps(result, indent=2))

    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()
